export declare const UPDATE_REQUISITION_LIST_MUTATION = "\n  mutation UPDATE_REQUISITION_LIST_MUTATION(\n      $requisitionListUid: ID!,\n      $name: String!,\n      $description: String,\n      $pageSize: Int,\n      $currentPage: Int\n    ) {\n    updateRequisitionList(\n      requisitionListUid: $requisitionListUid\n      input: {\n        name: $name\n        description: $description\n      }\n    ) {\n      requisition_list {\n        ...REQUISITION_LIST_FRAGMENT\n        items(pageSize: $pageSize, currentPage: $currentPage) {\n          ...REQUISITION_LIST_ITEMS_FRAGMENT\n        }\n      }\n    }\n  }\n\nfragment REQUISITION_LIST_FRAGMENT on RequisitionList {\n    uid\n    name\n    description\n    items_count\n    updated_at\n  }\n\n\nfragment REQUISITION_LIST_ITEMS_FRAGMENT on RequistionListItems {\n  items {\n    uid\n    quantity\n    product {\n      sku\n      stock_status\n      only_x_left_in_stock\n    }\n    customizable_options {\n      customizable_option_uid\n      is_required\n      label\n      sort_order\n      type\n      values {\n        customizable_option_value_uid\n        label\n        value\n        price {\n          type\n          units\n          value\n        }\n      }\n    }\n    ... on ConfigurableRequisitionListItem {\n      configurable_options {\n        configurable_product_option_uid\n        configurable_product_option_value_uid\n        option_label\n        value_label\n      }\n    }\n    ... on DownloadableRequisitionListItem {\n      links {\n        price\n        sample_url\n        sort_order\n        title\n        uid\n      }\n      samples {\n        sample_url\n        sort_order\n        title\n      }\n    }\n    ... on BundleRequisitionListItem {\n      bundle_options {\n        uid\n        type\n        label\n        values {\n          uid\n          label\n          quantity\n          priceV2 {\n            value\n            currency\n          }\n          original_price {\n            value\n            currency\n          }\n        }\n      }\n    }\n    ... on GiftCardRequisitionListItem {\n      gift_card_options {\n        amount {\n          currency\n          value\n        }\n        custom_giftcard_amount {\n          currency\n          value\n        }\n        message\n        recipient_email\n        recipient_name\n        sender_name\n        sender_email\n      }\n    }\n  }\n  page_info {\n    page_size\n    current_page\n    total_pages\n  }\n}\n\n";
